module majority (
    input a, b, c,
    output out
);
    wire nand3;
    wire nand2_1, nand2_2;

    // Majority function using NAND gates
    assign nand3 = a ~& (b ~& c);
    assign nand2_1 = a ~& b;
    assign nand2_2 = a ~& c;
    assign out = nand3 ~& (nand2_1 ~& nand2_2);

endmodule

