module bin_to_gray (
    input [3:0] binary,
    output [3:0] gray
);
    wire [3:0] A_sq;
    assign A_sq[3] = binary[3];
    assign A_sq[2] = binary[2] ^ binary[3];
    assign A_sq[1] = binary[1] ^ binary[3];
    assign A_sq[0] = binary[0] ^ binary[3];

    assign gray[3] = A_sq[3];
    assign gray[2] = A_sq[2];
    assign gray[1] = A_sq[1] ^ A_sq[2];
    assign gray[0] = A_sq[0];
endmodule

