module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);

    wire in0_bar, in1_bar;

    // Invert input bits
    not (in1_bar, in[1]);
    not (in0_bar, in[0]);

    // Generate AND terms for each output
    and (out[0], in1_bar, in0_bar);
    and (out[1], in1_bar, in[0]);
    and (out[2], in[1], in0_bar);
    and (out[3], in[1], in[0]);

endmodule

