module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);

    wire in0_bar, in1_bar;

    // Generate inverted inputs using NAND gates
    nand(in1_bar, in[1], in[1]);
    nand(in0_bar, in[0], in[0]);

    // Generate each output using NAND-based logic
    wire w0, w1, w2, w3;

    nand(w0, in1_bar, in0_bar);
    nand(out[0], w0, w0);

    nand(w1, in1_bar, in[0]);
    nand(out[1], w1, w1);

    nand(w2, in[1], in0_bar);
    nand(out[2], w2, w2);

    nand(w3, in[1], in[0]);
    nand(out[3], w3, w3);

endmodule

