module fsm_3state (
    input clk, reset,
    output [1:0] state
);

    localparam S0 = 2'b00,
               S1 = 2'b01,
               S2 = 2'b10,
               S3 = 2'b11;

    reg [1:0] current_state, next_state;

    always @(posedge clk) begin
        if (reset) begin
            current_state <= S0;
        end else begin
            current_state <= next_state;
        end
    end

    always @* begin
        next_state = current_state + 1;
        if (current_state == S3)
            next_state = S0;
    end

    assign state = current_state;

endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);
    parameter s0 = 2'b00,
              s1 = 2'b01,
              s2 = 2'b10,
              s3 = 2'b11; // Unused state

    reg [1:0] current_state, next_state;

    // State transition logic
    always @(posedge clk) begin
        if (reset)
            current_state <= s0;
        else
            current_state <= next_state;
    end

    // Next state combinational logic
    always @(*) begin
        case (current_state)
            s0: next_state = s1;
            s1: next_state = s2;
            s2: next_state = s3;
            s3: next_state = s0;
            default: next_state = s0; // Handle unexpected states
        endcase
    end

    // Output assignment
    assign state = current_state;
endmodule

