module traffic_light (
    input clk, reset,
    output [2:0] light
);

reg [1:0] current_state, next_state;

localparam S0 = 2'd0,
           S1 = 2'd1,
           S2 = 2'd2;

// State transition logic
always @(posedge clk) begin
    if (reset)
        current_state <= S0;
    else
        current_state <= next_state;
end

// Next state logic
always @(*) begin
    case (current_state)
        S0: next_state = S1;
        S1: next_state = S2;
        S2: next_state = S0;
        default: next_state = S0;
    endcase
end

// Output logic
assign light = (current_state == S0) ? 3'b100 :
               (current_state == S1) ? 3'b010 :
               (current_state == S2) ? 3'b001 :
               3'b000;

endmodule

