module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

    localparam [1:0] STATE_A = 2'b00,
                     STATE_B = 2'b01,
                     STATE_C = 2'b10;

    reg [1:0] state_reg, next_state;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state_reg <= STATE_A;
        end else begin
            state_reg <= next_state;
        end
    end

    always @(*) begin
        case (state_reg)
            STATE_A: begin
                if (up_request)
                    next_state = STATE_B;
                else if (down_request)
                    next_state = STATE_C;
                else
                    next_state = STATE_A;
            end
            STATE_B: begin
                if (up_request)
                    next_state = STATE_B;
                else
                    next_state = STATE_A;
            end
            STATE_C: begin
                if (down_request)
                    next_state = STATE_C;
                else
                    next_state = STATE_A;
            end
            default: next_state = STATE_A;
        endcase
    end

    assign state = state_reg;

endmodule

