module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

parameter UP = 2'b00,
          DOWN = 2'b01,
          WAIT = 2'b10;

reg [1:0] current_state, next_state;

always @(posedge clk or posedge reset) begin
    if (reset)
        current_state <= UP;
    else
        current_state <= next_state;
end

always @(*) begin
    case (current_state)
        UP: 
            next_state = down_request ? DOWN : UP;
        DOWN: 
            next_state = up_request ? WAIT : DOWN;
        WAIT: 
            next_state = up_request ? UP : WAIT;
        default: 
            next_state = UP;
    endcase
end

assign state = current_state;

endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

    localparam [1:0] UP    = 2'b00,
                     DOWN  = 2'b01,
                     STOP  = 2'b10;

    reg [1:0] state_reg, state_next;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state_reg <= UP;
        end else begin
            state_reg <= state_next;
        end
    end

    always @* begin
        case (state_reg)
            UP: begin
                if (up_request) begin
                    state_next = UP;
                end else begin
                    state_next = DOWN;
                end
            end
            DOWN: begin
                if (down_request) begin
                    state_next = DOWN;
                end else begin
                    state_next = UP;
                end
            end
            STOP: begin
                if (up_request) begin
                    state_next = UP;
                end else if (down_request) begin
                    state_next = DOWN;
                end else begin
                    state_next = STOP;
                end
            end
            default: begin
                state_next = UP;
            end
        endcase
    end

    assign state = state_reg;

endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

    // State encoding parameters
    localparam [1:0] UP    = 2'b00,
                     DOWN  = 2'b01,
                     STOP  = 2'b10;

    reg [1:0] current_state, next_state;

    // Sequential state update with asynchronous reset
    always @(posedge clk or posedge reset) begin
        if (reset)
            current_state <= UP;
        else
            current_state <= next_state;
    end

    // Combinational next state logic
    always @(*) begin
        case (current_state)
            UP: 
                next_state = down_request ? STOP : UP;
            DOWN: 
                next_state = up_request ? STOP : DOWN;
            STOP: begin
                if (up_request)
                    next_state = UP;
                else if (down_request)
                    next_state = DOWN;
                else
                    next_state = STOP;
            end
            default: 
                next_state = UP; // Handle unexpected states
        endcase
    end

    // Output current state
    assign state = current_state;

endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);
    parameter S0 = 2'b00,
              S1 = 2'b01,
              S2 = 2'b10;

    reg [1:0] current_state, next_state;

    // State register
    always @(posedge clk or posedge reset) begin
        if (reset)
            current_state <= S0;
        else
            current_state <= next_state;
    end

    // Next state logic
    always @(*) begin
        case (current_state)
            S0: begin
                if (coin_inserted)
                    next_state = S1;
                else if (item_selected)
                    next_state = S2;
                else
                    next_state = S0;
            end
            S1: begin
                if (coin_inserted)
                    next_state = S2;
                else if (item_selected)
                    next_state = S0;
                else
                    next_state = S1;
            end
            S2: begin
                if (coin_inserted)
                    next_state = S0;
                else if (item_selected)
                    next_state = S0;
                else
                    next_state = S2;
            end
            default: next_state = S0;
        endcase
    end

    assign state = current_state;
