module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

    // Define state parameters
    localparam [1:0] INIT   = 2'b00,
                     ACTIVE = 2'b01,
                     ERROR  = 2'b10;

    reg [1:0] current_state, next_state;

    // Sequential logic for state transitions and reset
    always @(posedge clk or posedge reset) begin
        if (reset)
            current_state <= INIT;
        else
            current_state <= next_state;
    end

    // Combinational logic for next state
    always @* begin
        next_state = current_state; // Default: stay in current state
        case (current_state)
            INIT: begin
                if (coin_inserted)
                    next_state = ACTIVE;
                else if (item_selected)
                    next_state = ERROR;
            end
            ACTIVE: begin
                if (coin_inserted)
                    next_state = ACTIVE;
                else if (item_selected)
                    next_state = ERROR;
            end
            ERROR: begin
                if (coin_inserted)
                    next_state = ACTIVE;
                else if (item_selected)
                    next_state = ERROR;
            end
            default: next_state = INIT; // Handle undefined states
        endcase
    end

    // Output current state
    assign state = current_state;

endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

    // State definitions
    localparam [1:0] S0 = 2'b00,
                     S5 = 2'b01,
                     S10 = 2'b10;

    reg [1:0] current_state, next_state;

    // State register with asynchronous reset
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= S0;
        end else begin
            current_state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        case (current_state)
            S0: begin
                if (coin_inserted)
                    next_state = S5;
                else if (item_selected)
                    next_state = S10;
                else
                    next_state = S0;
            end
            S5: begin
                if (coin_inserted)
                    next_state = S10;
                else if (item_selected)
                    next_state = S0; // Dispense item, reset to S0
                else
                    next_state = S5;
            end
            S10: begin
                if (coin_inserted)
                    next_state = S0; // Dispense item, reset to S0
                else if (item_selected)
                    next_state = S0; // Dispense item, reset to S0
                else
                    next_state = S10;
            end
            default: next_state = S0; // Handle undefined states
        endcase
    end

    // Output current state
    assign state = current_state;

