    reg [1:0] state_reg;

    // State transitions
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state_reg <= S0;
        end else begin
            case (state_reg)
                S0: begin
                    if (coin_inserted)
                        state_reg <= S5;
                    else if (item_selected)
                        state_reg <= S10;
                end
                S5: begin
                    if (coin_inserted)
                        state_reg <= S10;
                end
                S10: begin
                    // No transitions from S10
                end
                default: state_reg <= S0;
            endcase
        end
    end

    assign state = state_reg;

endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

    parameter [1:0] NO_COIN = 2'b00,
                    ONE_COIN = 2'b01,
                    ITEM = 2'b10;

    reg [1:0] current_state, next_state;

    always @(posedge clk or posedge reset) begin
        if (reset)
            current_state <= NO_COIN;
        else
            current_state <= next_state;
    end

    always @(*) begin
        case (current_state)
            NO_COIN: 
                next_state = coin_inserted ? ONE_COIN : NO_COIN;
            ONE_COIN: 
                next_state = item_selected ? ITEM : ONE_COIN;
            ITEM: 
                next_state = ITEM;
            default: 
                next_state = NO_COIN;
        endcase
    end

    assign state = current_state;

endmodule

