module log2_int (
    input signed [15:0] in_0,
    output signed [7:0] out
);

wire [3:0] upper_4 = in_0[15:12];
wire [3:0] lower_4 = in_0[11:8];
wire [3:0] middle_4 = in_0[7:4];
wire sign = in_0[15];

reg [3:0] adjusted_exponent;

always @(*) begin
    adjusted_exponent = lower_4;
    if (sign) begin
        adjusted_exponent = (adjusted_exponent == 4'd15) ? 4'd15 : adjusted_exponent + 1;
    end
    if (upper_4 != 4'd0) begin
        adjusted_exponent = adjusted_exponent + upper_4;
    end
end

assign out = {4'b0, adjusted_exponent};

endmodule

module log2_int (
    input signed [15:0] in_0,
    output signed [7:0] out
);

wire [3:0] tens;
wire [3:0] units;

assign tens = (in_0[15:12] >= 4'd1) ? 4'd1 :
              (in_0[15:12] == 4'd0 && in_0[11:8] >= 4'd2) ? 4'd2 :
              (in_0[15:12] == 4'd0 && in_0[11:8] == 4'd1 && in_0[7:4] >= 4'd3) ? 4'd3 :
              4'd0;

assign units = (in_0[15:12] == 4'd0) ? in_0[11:8] :
               (in_0[15:12] == 4'd1) ? in_0[7:4] :
               4'd0;

wire valid = (tens <= 4'd3) && (units <= 4'd9);
wire [7:0] digit = valid ? {4'b0, units} : 8'd0;

assign out = digit;

endmodule

module log2_int (
