wire lower_2_or_lower_4_neq_0 = lower_2_neq_0 || (mid_4 != 4'b0);
wire upper_4_or_lower_4_neq_0 = (upper_4 != 4'b0) || (lower_4 != 4'b0);

assign out = upper_4_or_lower_4_neq_0 ? 
    (upper_4_or_lower_2_or_lower_4_neq_0 ? 8'd1 : 8'd2) :
    (lower_2_or_lower_4_neq_0 ? 8'd4 : 8'd8) :
    8'd16;

endmodule

