module add_8bit (
    input signed [7:0] a, b,
    output signed [8:0] out
);

    wire [7:0] b_adj = { {1{~b[7]} }, ~b }; // Invert b and sign-extend

    // Compute carry-propagate and generate blocks
    wire [7:0] p, g;
    generate
        genvar i;
        for (i=0; i<8; i=i+1) begin : pg
            assign p[i] = a[i] ^ b_adj[i];
            assign g[i] = a[i] & b_adj[i];
        end
    endgenerate

    // Carry Lookahead logic
    wire [8:1] c;
    assign c[1] = g[0];
    generate
        for (i=2; i<=8; i=i+1) begin : cl
            assign c[i] = g[i-1] | (p[i-1] & c[i-2]);
        end
    endgenerate

    // Sum computation
    assign out = {c[8], p};

endmodule

