module mult_4bit (
    input [3:0] a, b,
    output [7:0] out
);
    wire [3:0] p, g;

    // Generate and propagate signals
    assign g = a & b;
    assign p = a ^ b;

    // Carry computation using Kogge-Stone prefix tree
    wire c0, c1, c2, c3, c4, c5, c6;

    // Stage 1: Span 1
    wire s1_1, s1_2, s1_3, s1_4;
    assign s1_1 = g[0] | (p[0] & g[1]);
    assign s1_2 = g[1] | (p[1] & g[2]);
    assign s1_3 = g[2] | (p[2] & g[3]);
    assign s1_4 = g[3] | (p[3] & g[0]);

    // Stage 2: Span 2
    wire s2_1, s2_2;
    assign s2_1 = s1_1 | (p[0] & s1_2);
    assign s2_2 = s1_2 | (p[1] & s1_3);

    // Stage 3: Span 4
    assign c4 = s1_4 | (p[2] & s1_1) | (p[2] & p[1] & s1_2);

    // Compute carries for each bit
    assign c0 = g[0];
    assign c1 = g[1] | (p[1] & g[0]);
    assign c2 = g[2] | (p[2] & g[1]) | (p[2] & p[1] & g[0]);
    assign c3 = g[3] | (p[3] & g[2]) | (p[3] & p[2] & g[1]) | (p[3] & p[2] & p[1] & g[0]);
    assign c4 = c4; // Carry-out from LSB

    // Sum computation
    assign out[0] = p[0] ^ c0;
    assign out[1] = p[1] ^ c1;
    assign out[2] = p[2] ^ c2;
    assign out[3] = p[3] ^ c3;
    assign out[4] = c4;
    assign out[5] = p[0] ^ c0;
    assign out[6] = p[1] ^ c1;
    assign out[7] = p[2] ^ c2;
endmodule

