module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);

    wire eq3, eq2, eq1, eq0;
    wire term1, term2, term3, term4;
    wire A_gt_B, A_lt_B, A_eq_B;

    // Equality bits
    xor (eq3, a[3], b[3]);
    xor (eq2, a[2], b[2]);
    xor (eq1, a[1], b[1]);
    xor (eq0, a[0], b[0]);

    // All equal (A_eq_B)
    and (term1, eq3, eq2);
    and (term2, term1, eq1);
    and (term3, term2, eq0);
    and (A_eq_B, term3, term3); // term3 is AND of all eq bits

    // Greater than (A_gt_B)
    nand (term4, a[3], b[3]);
    nand (term4, term4, term4); // term4 = ~a[3]|~b[3] (a[3]>b[3])
    nand (term4, term4, eq3);
    nand (term4, term4, term1);
    nand (term4, term4, eq2);
    nand (term4, term4, term1);
    nand (term4, term4, eq1);
    nand (term4, term4, term3);
    nand (A_gt_B, term4, term4); // term4 now a3> b3 and a2==b2, etc.

    // Less than (A_lt_B)
    nand (term4, b[3], a[3]);
    nand (term4, term4, term4); // term4 = a3< b3
    nand (term4, term4, eq3);
    nand (term4, term4, term1);
    nand (term4, term4, eq2);
    nand (term4, term4, term1);
    nand (term4, term4, eq1);
    nand (term4, term4, term3);
    nand (A_lt_B, term4, term4);

    // Outputs
    nand (gt, A_gt_B, A_gt_B);
    nand (lt, A_lt_B, A_lt_B);
    not (eq, A_eq_B); // A_eq_B is already AND of all eq bits

endmodule

