module up_counter8(
    input clk,
    input rst,
    output [7:0] count
);

reg [7:0] q_reg;
wire [7:0] t;

assign t[0] = 1'b1;

genvar i;
generate
    for (i = 1; i < 8; i = i + 1) begin : gen_toggle
        assign t[i] = &q_reg[i-1:0];
    end
endgenerate

always @(posedge clk) begin
    if (rst) begin
        q_reg <= 8'b0;
    end else begin
        for (integer j = 0; j < 8; j = j + 1) begin
            q_reg[j] <= q_reg[j] ^ t[j];
        end
    end
end

assign count = q_reg;

endmodule

module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  localparam [1:0] IDLE      = 2'b00,
                   SET_SECOND= 2'b01,
                   SET_MIN    = 2'b10,
                   READY      = 2'b11;

  reg [1:0] current_state, next_state;

  // State register
  always @(posedge clk) begin
    if (!resetn)
      current_state <= IDLE;
    else
      current_state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      IDLE:      next_state = resetn ? SET_SECOND : IDLE;
      SET_SECOND: next_state = (r == 3) ? SET_MIN : SET_SECOND;
      SET_MIN:   next_state = (r == 6) ? READY : SET_MIN;
      READY:     next_state = READY;
      default:   next_state = IDLE;
    endcase
  end

  // Output logic
  assign g = (!resetn) ? 3'b000 :
             (current_state == IDLE)       ? 3'b001 :
             (current_state == SET_SECOND) ? 3'b011 :
             (current_state == SET_MIN)    ? 3'b111 :
             3'b000; // READY and others

endmodule

module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  localparam [1:0] IDLE     = 2'b00,
                   SET_SEC  = 2'b01,
                   SET_MIN  = 2'b10,
                   READY    = 2'b11;

  reg [1:0] current_state, next_state;

  always @(posedge clk) begin
    if (!resetn)
      current_state <= IDLE;
    else
      current_state <= next_state;
  end

  always @(*) begin
    case (current_state)
      IDLE:    next_state = (r == 3'b000) ? SET_SEC : IDLE;
      SET_SEC: next_state = (r == 3'b001) ? SET_MIN : (r == 3'b111) ? READY : SET_SEC;
      SET_MIN: next_state = (r == 3'b010) ? IDLE : (r == 3'b111) ? READY : SET_MIN;
      READY:   next_state = (r == 3'b000) ? SET_SEC : READY;
      default: next_state = IDLE;
    endcase
  end

  assign g = (current_state == READY) ? 3'b111 : 3'b000;

endmodule

