      RECIEPLEB2:  next_state = (r == 0) ? FINISH : STRT;
      FINISH:      next_state = (r == 7) ? FINISH : STRT;
      default:     next_state = STRT;
    endcase
  end

  assign g = (current_state == STRT)    ? 3'b100 :
              (current_state == RECIEPLEB)   ? 3'b110 :
              (current_state == RECIEPLEB2) ? 3'b010 :
              3'b001;

endmodule

module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  // Define states
  localparam [1:0] IDLE = 2'b00,
                   GNT1 = 2'b01,
                   GNT2 = 2'b10,
                   GNT3 = 2'b11;

  reg [1:0] current_state, next_state;

  // Next state logic
  always @* begin
    case (current_state)
      IDLE: begin
        if (r[0])
          next_state = GNT1;
        else if (r[1])
          next_state = GNT2;
        else if (r[2])
          next_state = GNT3;
        else
          next_state = IDLE;
      end
      GNT1: next_state = r[0] ? GNT1 : IDLE;
      GNT2: next_state = r[1] ? GNT2 : IDLE;
      GNT3: next_state = r[2] ? GNT3 : IDLE;
      default: next_state = IDLE;
    endcase
  end

  // State transition with synchronous reset
  always @(posedge clk) begin
    if (!resetn)
      current_state <= IDLE;
    else
      current_state <= next_state;
  end

  // Output logic based on current state
  assign g = (current_state == IDLE)  ? 3'b000 :
             (current_state == GNT1) ? 3'b001 :
             (current_state == GNT2) ? 3'b010 :
             (current_state == GNT3) ? 3'b100 :
             3'b000;

endmodule

module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  parameter S0 = 2'b00;
  parameter S1 = 2'b01;
  parameter S2 = 2'b10;
  parameter S3 = 2'b11;

  reg [1:0] state, next_state;

  always @(posedge clk) begin
    if (!resetn)
      state <= S0;
    else
      state <= next_state;
  end

  always @(*) begin
    case (state)
      S0: begin
        if (r[0])
          next_state = S0;
        else if (r[1])
          next_state = S1;
        else if (r[2])
          next_state = S2;
        else
          next_state = S3;
      end
      S1: begin
        if (r[0])
          next_state = S0;
        else if (r[1])
          next_state = S1;
        else if (r[2])
          next_state = S2;
        else
          next_state = S3;
      end
      S2: begin
        if (r[0])
          next_state = S0;
        else if (r[1])
          next_state = S1;
        else if (r[2])
          next_state = S2;
        else
          next_state = S3;
      end
      S3: begin
        if (r[0])
          next_state = S0;
        else if (r[1])
          next_state = S1;
        else if (r[2])
          next_state = S2;
        else
          next_state = S3;
      end
      default: next_state = S0;
    endcase
  end

  assign g[0] = (state == S0);
  assign g[1] = (state == S1);
  assign g[2] = (state == S2);

endmodule

