module TopModule (
  input cpu_overheated,
  output reg shut_off_computer,
  input arrived,
  input gas_tank_empty,
  output reg keep_driving
);

  reg [2:0] state, next_state;

  localparam IDLE      = 3'b000,
             FARMING   = 3'b001,
             STOPPING  = 3'b010,
             RESETTING = 3'b011;

  always @(*) begin
    shut_off_computer = (state == IDLE) ? 1'b1 : 1'b0;
    keep_driving = (next_state == FARMING) ? 1'b1 : 1'b0;
  end

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      state <= IDLE;
    end else begin
      state <= next_state;
    end
  end

  always @(*) begin
    case (state)
      IDLE:      next_state = cpu_overheated ? STOPPING : FARMING;
      FARMING:   next_state = arrived ? IDLE : FARMING;
      STOPPING:  next_state = gas_tank_empty ? RESETTING : STOPPING;
      RESETTING: next_state = IDLE;
      default:   next_state = IDLE;
    endcase
  end

endmodule

