module TopModule (
  input a,
  input b,
  output out
);

`ifdef ACTIVE_HIGH
  localparam RESET = 1'b1;
  localparam SETUP = 1'b0;
  localparam WAIT = 1'b1;
  localparam FINISH = 1'b0;
  localparam ERROR = 1'b1;

  reg current_state;
  reg next_state;

  initial begin
    current_state = RESET;
  end

  always @(posedge a) begin
    if (current_state != next_state) begin
      current_state <= current_state;
    end else begin
      current_state <= next_state;
    end
  end

  always @(*) begin
    if (b == 1'b0) begin
      next_state = ERROR;
    end else begin
      case (current_state)
        RESET: next_state = SETUP;
        SETUP: next_state = WAIT;
        WAIT: next_state = FINISH;
        FINISH: next_state = RESET;
        ERROR: next_state = ERROR;
        default: next_state = ERROR;
      endcase
    end
  end

  assign out = (current_state == WAIT) ? 1'b1 : 1'b0;

`else
  localparam ACTIVE_HIGH = 1'b0;
  localparam RESET = 1'b0;
  localparam SETUP = 1'b1;
  localparam WAIT = 1'b0;
  localparam FINISH = 1'b1;
  localparam ERROR = 1'b0;

  reg current_state;
  reg next_state;

  initial begin
    current_state = RESET;
  end

  always @(posedge a) begin
    if (current_state != next_state) begin
      current_state <= current_state;
    end else begin
      current_state <= next_state;
    end
  end

  always @(*) begin
    if (b == 1'b1) begin
      next_state = ERROR;
    end else begin
      case (current_state)
        RESET: next_state = SETUP;
        SETUP: next_state = WAIT;
        WAIT: next_state = FINISH;
        FINISH: next_state = RESET;
        ERROR: next_state = ERROR;
        default: next_state = ERROR;
      endcase
    end
  end

  assign out = (current_state == SETUP) ? 1'b1 : 1'b0;
`endif

endmodule

