module TopModule (
  input clk,
  input areset,
  input train_valid,
  input train_taken,
  output logic [1:0] state
);

  // State encoding parameters
  localparam [1:0] IDLE  = 2'b00,
                   TRAIN = 2'b01,
                   TEST  = 2'b10,
                   APPLY = 2'b11;

  reg [1:0] current_state, next_state;

  // State register with asynchronous reset
  always @(posedge clk or posedge areset) begin
    if (areset)
      current_state <= IDLE;
    else
      current_state <= next_state;
  end

  // Next state combinational logic
  always @(*) begin
    case (current_state)
      IDLE: begin
        next_state = (train_valid && train_taken) ? TRAIN : IDLE;
      end
      TRAIN: begin
        next_state = (train_valid && train_taken) ? TEST : TRAIN;
      end
      TEST: begin
        next_state = (train_valid && train_taken) ? APPLY : TEST;
      end
      APPLY: begin
        next_state = APPLY; // Transition remains in APPLY
      end
      default: next_state = IDLE;
    endcase
  end

  // Output assignment
  assign state = current_state;

endmodule

