module TopModule (
  input clk,
  input j,
  input k,
  input areset,
  output out
);

  // M1 parameters
  parameter DELAY    = 0;
  parameter D1_WIDTH = 1;
  parameter D2_WIDTH = 1;

  // S1 parameters
  parameter DELAY_S1 = 0;
  parameter D1_WIDTH_S1 = 1;
  parameter D2_WIDTH_S1 = 1;

  reg s1;
  reg s2;

  // S1 state update
  always @(posedge clk or posedge areset) begin
    if (areset) begin
      s1 <= 1'b0;
    end else begin
      case ({j, k})
        2'b01: s1 <= 1'b0;   // Set to 0 when j=1, k=0
        2'b10: s1 <= 1'b1;   // Set to 1 when k=1, j=0
        default: s1 <= s1;   // Hold state otherwise
      endcase
    end
  end

  // S2 state update
  always @(posedge clk or posedge areset) begin
    if (areset) begin
      s2 <= 1'b0;
    end else begin
      case ({s1, DELAY_S1})
        2'b01: s2 <= 1'b0;   // Set to 0 when s1=0, DELAY_S1=1
        2'b10: s2 <= 1'b1;   // Set to 1 when s1=1, DELAY_S1=2
        default: s2 <= s2;   // Hold state otherwise
      endcase
    end
  end

  // Output assignments with delays
  assign #DELAY out = s2;
  assign #DELAY_S1 out = s1;

  // Unused wires
  wire [D1_WIDTH-1:0] u1;
  wire [D2_WIDTH-1:0] u2;
  wire [D1_WIDTH_S1-1:0] u3;
  wire [D2_WIDTH_S1-1:0] u4;

endmodule

