module TopModule (
  input [3:0] x,
  input [3:0] y,
  output [4:0] sum
);

  wire [3:0] P, G;
  wire c1, c2, c3, c4;

  assign P = x ^ y;
  assign G = x & y;

  // Carry Lookahead Logic
  assign c1 = G[0];
  assign c2 = G[1] | (P[1] & G[0]);
  assign c3 = G[2] | (P[2] & G[1]) | (P[2] & P[1] & G[0]);
  assign c4 = G[3] | (P[3] & G[2]) | (P[3] & P[2] & G[1]) | (P[3] & P[2] & P[1] & G[0]);

  // Sum Calculation
  assign sum[0] = P[0];          // c0 = 0
  assign sum[1] = P[1] ^ c1;
  assign sum[2] = P[2] ^ c2;
  assign sum[3] = P[3] ^ c3;
  assign sum[4] = c4;

endmodule

