module TopModule (
  input clk,
  input reset,
  input w,
  output z
);

  parameter S0 = 3'd0,
            S1 = 3'd1,
            S2 = 3'd2,
            S3 = 3'd3,
            S4 = 3'd4;

  reg [2:0] current_state, next_state;

  // State transition logic
  always @(posedge clk) begin
    if (reset)
      current_state <= S0;
    else
      current_state <= next_state;
  end

  // Next state combinational logic
  always @(*) begin
    case (current_state)
      S0: next_state = w ? S1 : S0;
      S1: next_state = w ? S1 : S2;
      S2: next_state = w ? S3 : S0;
      S3: next_state = w ? S4 : S2;
      S4: next_state = w ? S1 : S2;
      default: next_state = S0;
    endcase
  end

  // Output logic
  assign z = (current_state == S2 || current_state == S4);

endmodule

