module TopModule (
  input [7:0] in,
  output parity
);

  // Function to compute XOR of two bits
  function automatic logic xor_func(input a, input b);
    xor_func = a ^ b;
  endfunction

  // Temporary wire array to accumulate XOR results
  wire [7:0] temp;

  // Generate block to iteratively compute parity
  genvar i;
  generate
    assign temp[0] = in[0]; // Initialize with the first bit
    for (i = 1; i < 8; i = i + 1) begin : gen_parity
      assign temp[i] = xor_func(temp[i-1], in[i]); // XOR accumulation
    end
  endgenerate

  assign parity = temp[7]; // Final result is the accumulated XOR

endmodule

