module TopModule (
  input clk,
  input a,
  input b,
  output q,
  output state
);

  localparam state0 = 1'b0;
  localparam state1 = 1'b1;
  reg current_state, next_state;

  // State transition
  always @(posedge clk) begin
    current_state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      state0: next_state = (a == b) ? state1 : state0;
      state1: next_state = state1;
      default: next_state = state0;
    endcase
  end

  // Output logic
  assign q = (current_state == state0) ? (a == b) : ~(a == b);
  assign state = current_state;

  // Initial state
  initial begin
    current_state = state0;
  end

endmodule

