      BOX: next_state = (a == 1'b0 && b == 1'b0) ? BOX : 1'b0;
      default: next_state = BOX;
    endcase
  end

  // State transition on clock edge
  always @(posedge clk) begin
    current_state <= next_state;
  end

  // Output assignments
  assign q = (current_state == BOX) ? (a ^ b) : 1'bx;
  assign state = current_state;

