  wire [2:0] N_minus_1 = 3'd4;
  wire [2:0] half = 3'd2;

  always @(posedge clk) begin
    if (a) begin
      q <= 3'd1;
    end else begin
      if (q == N) begin
        q <= 3'd1;
      end else if (q > half) begin
        q <= N_minus_1;
      end else begin
        q <= q + 3'd1;
      end
    end
  end

