module TopModule (
  input clk,
  input areset,
  input x,
  output z
);

  localparam S0 = 2'b00,
             S1 = 2'b01,
             S2 = 2'b10;

  reg [1:0] current_state, next_state;

  always @(posedge clk or posedge areset) begin
    if (areset)
      current_state <= S0;
    else
      current_state <= next_state;
  end

  always @(*) begin
    case (current_state)
      S0: next_state = x ? S1 : S2;
      S1: next_state = S0;
      S2: next_state = S0;
      default: next_state = S0;
    endcase
  end

  assign z = (current_state == S1 && x) || (current_state == S2 && !x);

endmodule

