  always @(posedge clk or posedge areset) begin
    if (areset) begin
      state <= RIGHT;
    end else begin
      case (state)
        RIGHT: state <= (bump_left) ? LEFT : RIGHT;
        LEFT:  state <= (bump_right) ? RIGHT : LEFT;
        default: state <= RIGHT;
      endcase
    end
  end

  assign walk_left = (state == LEFT);
  assign walk_right = (state == RIGHT);

