      case (state)
        STATE_WALK_RIGHT: 
          if (bump_left) state <= STATE_WALK_LEFT;
          else state <= STATE_WALK_RIGHT;
        STATE_WALK_LEFT: 
          if (bump_right) state <= STATE_WALK_RIGHT;
          else state <= STATE_WALK_LEFT;
        default: state <= STATE_WALK_RIGHT;
      endcase
    end
  end

