module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  output walk_left,
  output walk_right,
  output aaah
);

  reg [1:0] state, next_state;
  localparam WAIT = 2'b00,
             COIN = 2'b01,
             LEFT = 2'b10,
             RIGHT = 2'b11;

  // State register
  always @(posedge clk or posedge areset) begin
    if (areset)
      state <= WAIT;
    else
      state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (state)
      WAIT: begin
        if (ground)
          next_state = COIN;
        else if (bump_left)
          next_state = LEFT;
        else if (bump_right)
          next_state = RIGHT;
        else
          next_state = WAIT;
      end
      COIN: next_state = WAIT;
      LEFT: next_state = (ground) ? COIN : LEFT;
      RIGHT: next_state = (ground) ? COIN : RIGHT;
      default: next_state = WAIT;
    endcase
  end

  // Output logic
  assign walk_left = (state == LEFT);
  assign walk_right = (state == RIGHT);
  assign aaah = (state == COIN) || (state == RIGHT);

endmodule

module TopModule (
