  input bump_right,
  input ground,
  output walk_left,
  output walk_right,
  output aaah
);

  // State definitions
  localparam [1:0] ST_STOP = 2'b00,
                   ST_LEFT = 2'b01,
                   ST_RIGHT = 2'b10,
                   ST_AR_MV = 2'b11;

  reg [1:0] current_state, next_state;

  // State register
  always @(posedge clk or posedge areset) begin
    if (areset)
      current_state <= ST_STOP;
    else
      current_state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      ST_STOP: begin
        if (ground)
          next_state = ST_AR_MV;
        else if (bump_left)
          next_state = ST_LEFT;
        else if (bump_right)
          next_state = ST_RIGHT;
        else
          next_state = ST_STOP;
      end
      ST_LEFT: begin
        if (ground)
          next_state = ST_AR_MV;
        else if (bump_left)
          next_state = ST_LEFT;
        else
          next_state = ST_STOP;
      end
      ST_RIGHT: begin
        if (ground)
          next_state = ST_AR_MV;
        else if (bump_right)
          next_state = ST_RIGHT;
        else
          next_state = ST_STOP;
      end
      ST_AR_MV: begin
        if (ground)
          next_state = ST_AR_MV;
        else if (bump_left)
          next_state = ST_LEFT;
        else if (bump_right)
          next_state = ST_RIGHT;
        else
          next_state = ST_STOP;
      end
      default: next_state = ST_STOP;
    endcase
  end

  // Output logic
  assign walk_left = (current_state == ST_LEFT);
  assign walk_right = (current_state == ST_RIGHT);
  assign aaah = (current_state == ST_STOP) || (current_state == ST_AR_MV);

endmodule

