module TopModule (
  input clk,
  input reset,
  input data,
  output start_shifting
);

  reg [2:0] shift_reg;
  reg start_shifting_reg;

  always @(posedge clk) begin
    if (reset) begin
      shift_reg <= 3'b0;
      start_shifting_reg <= 1'b0;
    end else begin
      shift_reg <= {shift_reg[1:0], data};
      if (shift_reg == 3'b111) begin
        start_shifting_reg <= 1'b1;
      end else if (shift_reg == 3'b000) begin
        start_shifting_reg <= 1'b0;
      end
    end
  end

  assign start_shifting = start_shifting_reg;

endmodule

module TopModule (
