      if ({shift_reg[1:0], data} == 3'b111) begin
        start_shifting_reg <= 1'b1;
      end else if ( ({shift_reg[1:0], data} == 3'b000) || 
                   ( ({shift_reg[1:0], data} == 3'b111) && start_shifting_reg ) ) begin
        start_shifting_reg <= 1'b0;
