             if (i==1) begin
                 assign sum_lower[i] = A_31[i] ^ B_31[i] ^ Cin;
                 assign carry_i = (A_31[i] & B_31[i]) | (A_31[i] & Cin) | (B_31[i] & Cin);
             end else begin
                 assign sum_lower[i] = A_31[i] ^ B_31[i] ^ carry_i;
                 assign carry_i = (A_31[i] & B_31[i]) | (A_31[i] & carry_i) | (B_31[i] & carry_i);
             end
         end
     endgenerate
     assign carry_lower = carry_i;

     // Upper 16 bits with carry_lower
     for (i=17; i<=32; i=i+1) begin: upper_adder
         wire carry_i;
         if (i==17) begin
             assign S[i] = A_31[i] ^ B_31[i] ^ carry_lower;
             assign carry_i = (A_31[i] & B_31[i]) | (A_31[i] & carry_lower) | (B_31[i] & carry_lower);
         end else begin
             assign S[i] = A_31[i] ^ B_31[i] ^ carry_i;
             assign carry_i = (A_31[i] & B_31[i]) | (A_31[i] & carry_i) | (B_31[i] & carry_i);
         end
     end
     assign C32 = carry_i;

     assign S[32] = Cout;

endmodule

module adder_32bit(A,B,S,C32);
     input [32:1] A;
     input [32:1] B;
     output [32:1] S;
     output C32;

     wire [15:1] G;
     wire [15:1] P;
     wire [16:1] C;
     wire Cout;
     wire [31:1] S_upper;
     wire Cin;
     wire [32:1] S_lower;

     // Compute G and P using NOR and NAND gates respectively
     genvar i;
     generate
         for (i=1; i<=15; i=i+1) begin: gp
               assign G[i] = ~(A[i] | B[i]);
               assign P[i] = ~(A[i] & B[i]);
         end
     endgenerate

     // Carry computation using Kogge-Stone prefix tree
     assign C[1] = 1'b0;
     assign C[2] = P[1];
     assign C[3] = P[2] | (P[1] & C[2]);
     assign C[4] = P[3] | (P[2] & C[3]);
     assign C[5] = P[4] | (P[3] & C[4]);
     assign C[6] = P[5] | (P[4] & C[5]);
     assign C[7] = P[6] | (P[5] & C[6]);
     assign C[8] = P[7] | (P[6] & C[7]);
     assign C[9] = P[8] | (P[7] & C[8]);
     assign C[10] = P[9] | (P[8] & C[9]);
     assign C[11] = P[10] | (P[9] & C[10]);
     assign C[12] = P[11] | (P[10] & C[11]);
     assign C[13] = P[12] | (P[11] & C[12]);
     assign C[14] = P[13] | (P[12] & C[13]);
     assign C[15] = P[14] | (P[13] & C[14]);
     assign Cout = P[15] | (P[14] & C[15]);

     // Sum computation
     assign S[1] = A[1] ^ B[1] ^ C[1];
     generate
         for (i=2; i<=31; i=i+1) begin: sum
               assign S[i] = A[i] ^ B[i] ^ C[i-1];
         end
     endgenerate

     // Propagate Cin using NAND gates
     assign Cin = B[32] & A[32];
     genvar j;
     for (j=31; j>=1; j=j-1) begin: prop_cin
         assign S_upper[j] = A[j] ^ B[j] ^ Cin;
         assign Cin = B[j] & A[j];
     end

     // Concatenate S_upper and S[15:1]
     assign S[32] = C[15];
     assign S[31:16] = S_upper;
     assign S[15:1] = S_lower;

     assign C32 = Cout;
endmodule

module adder_32bit(A,B,S,C32);
     input [32:1] A;
     input [32:1] B;
     output [32:1] S;
     output C32;

     // Propagate and Generate signals for each bit
     wire [32:1] P, G;
     wire [32:0] C;

     // Compute P and G for each bit (assuming A[0] and B[0] are part of the input despite index constraints)
     assign P = A[0] | B[0];  // Assuming bit 0 for demonstration
     assign G = A[0] & B[0];

     // Carry computation for each bit
     assign C[0] = 1'b0;  // Initial carry-in is 0
     generate
         genvar i;
         for (i=1; i<32; i=i+1) begin : carry_chain
             assign C[i] = (P[i] & C[i-1]) | G[i];
         end
     endgenerate

     // Compute the sum bits
     assign S[32] = (A[32] ^ B[32]) ^ C[31];
     generate
         for (i=1; i<32; i=i+1) begin : sum_bits
             assign S[i] = (A[i] ^ B[i]) ^ C[i-1];
         end
     endgenerate

     // Final carry-out
     assign C32 = C[32];

     // Handle the inconsistent A[31] input by forcing it to 0
     assign S[16] = 1'b0;  // This line assumes A[16] was meant to be A[31]

endmodule

module adder_8bit(
    input [7:0] a, b, 
    input cin, 
    output [7:0] sum, 
    output cout);

wire [7:0] c; // Carry wires between stages

// Bit 0 (LSB)
assign c[0] = (a[0] & b[0]) | ((a[0] ^ b[0]) & cin);
assign sum[0] = (a[0] ^ b[0]) ^ cin;

// Bit 1
assign c[1] = (a[1] & b[1]) | ((a[1] ^ b[1]) & c[0]);
assign sum[1] = (a[1] ^ b[1]) ^ c[0];

// Bit 2
assign c[2] = (a[2] & b[2]) | ((a[2] ^ b[2]) & c[1]);
assign sum[2] = (a[2] ^ b[2]) ^ c[1];

// Bit 3
assign c[3] = (a[3] & b[3]) | ((a[3] ^ b[3]) & c[2]);
assign sum[3] = (a[3] ^ b[3]) ^ c[2];

// Bit 4
assign c[4] = (a[4] & b[4]) | ((a[4] ^ b[4]) & c[3]);
assign sum[4] = (a[4] ^ b[4]) ^ c[3];

// Bit 5
assign c[5] = (a[5] & b[5]) | ((a[5] ^ b[5]) & c[4]);
assign sum[5] = (a[5] ^ b[5]) ^ c[4];

// Bit 6
assign c[6] = (a[6] & b[6]) | ((a[6] ^ b[6]) & c[5]);
assign sum[6] = (a[6] ^ b[6]) ^ c[5];

// Bit 7 (MSB)
assign c[7] = (a[7] & b[7]) | ((a[7] ^ b[7]) & c[6]);
assign sum[7] = (a[7] ^ b[7]) ^ c[6];

// Carry-out is the final carry
assign cout = c[7];

endmodule

module adder_8bit(
