    generate
        for (i = 0; i < 8; i = i + 1) begin : adder_stage
            wire p, g;
            assign p = a[i] ^ b[i];
            assign g = a[i] & b[i];
            assign sum[i] = p ^ carry[i];
            assign carry[i+1] = g | (p & carry[i]);
        end
    endgenerate

    assign cout = carry[8];
