module adder_bcd (
    input  [3:0] A,   // First BCD number (0-9)
    input  [3:0] B,   // Second BCD number (0-9)
    input  Cin,       // Input carry
    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry
);

    // Initialize borrow and carry signals
    wire borrow = 1'b0;
    wire carry = 1'b0;

    // Process each bit from LSB (bit 0) to MSB (bit 3)
    assign Sum[0] = (A[0] + B[0] + Cin) >= 2 ? (A[0] + B[0] + Cin - 1'b1) : (A[0] + B[0] + Cin);
    assign carry = (A[0] + B[0] + Cin) >= 2 ? 1'b1 : 1'b0;
    assign Sum[1] = (A[1] + B[1] + carry) >= 2 ? (A[1] + B[1] + carry - 1'b1) : (A[1] + B[1] + carry);
    assign Cout = (A[1] + B[1] + carry) >= 2 ? 1'b1 : 1'b0;
    assign Sum[2] = (A[2] + B[2] + Cout) >= 2 ? (A[2] + B[2] + Cout - 1'b1) : (A[2] + B[2] + Cout);
    assign Sum[3] = (A[3] + B[3] + borrow) >= 2 ? (A[3] + B[3] + borrow - 1'b1) : (A[3] + B[3] + borrow);

endmodule

module adder_bcd (
    input  [3:0] A,   // First BCD number (0-9)
    input  [3:0] B,   // Second BCD number (0-9)
    input  Cin,       // Input carry
    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry
);

    // The output is 0 if A > B and Cin is 0 (no need to add), else compute sum and carry
    assign Sum = (A <= B || Cin) ? (A + B + Cin) : 4'd0;
    assign Cout = (A > B && Cin) ? 1'b1 : 1'b0;

endmodule

module adder_bcd (
    input  [3:0] A,   // First BCD number (0-9)
    input  [3:0] B,   // Second BCD number (0-9)
    input  Cin,       // Input carry
    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry
);

    // Precompute G0 and P0 for each digit
    wire [3:0] G0, P0;
    assign G0 = A & B;
    assign P0 = A ^ B;

    // Stage 1: Combine with initial carry (0)
    wire [3:0] G1, P1;
    wire C1_0, C1_1, C1_2, C1_3;

    // Digit 0 (LSB)
    assign C1_0 = G0[0] | (P0[0] & 1'b0); // G0[0] is A[0]&B[0], P0[0] is A[0]^B[0]
    assign G1[0] = G0[0] & P1[0];
    assign P1[0] = P0[0] ^ 1'b0;

    // Digit 1
    assign C1_1 = G0[1] | (P0[1] & C1_0);
    assign G1[1] = G0[1] & P1[1];
    assign P1[1] = P0[1] ^ C1_0;

    // Digit 2
    assign C1_2 = G0[2] | (P0[2] & C1_1);
    assign G1[2] = G0[2] & P1[2];
    assign P1[2] = P0[2] ^ C1_1;

    // Digit 3 (MSB)
    assign C1_3 = G0[3] | (P0[3] & C1_2);
    assign G1[3] = G0[3] & P1[3];
    assign P1[3] = P0[3] ^ C1_2;

    // Stage 2: Combine intermediate carry (C1_3)
    wire [3:0] G2, P2;
    wire C2_0, C2_1, C2_2, C2_3;

    // Digit 0 (LSB)
    assign C2_0 = G1[0] | (P1[0] & 1'b0);
    assign G2[0] = G1[0] & P2[0];
    assign P2[0] = P1[0] ^ 1'b0;

    // Digit 1
    assign C2_1 = G1[1] | (P1[1] & C2_0);
    assign G2[1] = G1[1] & P2[1];
    assign P2[1] = P1[1] ^ C2_0;

    // Digit 2
    assign C2_2 = G1[2] | (P1[2] & C2_1);
    assign G2[2] = G1[2] & P2[2];
    assign P2[2] = P1[2] ^ C2_1;

    // Digit 3 (MSB)
    assign C2_3 = G1[3] | (P1[3] & C2_2);
    assign G2[3] = G1[3] & P2[3];
    assign P2[3] = P1[3] ^ C2_2;

    // Compute sum bits and carry-out
    assign Sum[0] = P0[0] ^ 1'b0;          // A[0]^B[0]
    assign Sum[1] = P0[1] ^ C1_0;          // A[1]^B[1] ^ C1_0
    assign Sum[2] = P0[2] ^ C1_1;          // A[2]^B[2] ^ C1_1
    assign Sum[3] = P0[3] ^ C1_2;          // A[3]^B[3] ^ C1_2
    assign Cout  = C2_3;                   // Final carry-out

endmodule

module adder_bcd (
    input  [3:0] A,   // First BCD number (0-9)
    input  [3:0] B,   // Second BCD number (0-9)
    input  Cin,       // Input carry
    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry
);

    // Calculate numeric values of BCD inputs
    wire [3:0] a_num = A; // Direct assignment for 0-9 range
    wire [3:0] b_num = B;

    // Compute sum and carry using 5-bit precision
    wire [4:0] sum_temp = a_num + b_num + Cin;
    wire [3:0] sum_temp_trunc = sum_temp[3:0];
    wire carry_temp = sum_temp[4];

    // Check if sum exceeds 9 and adjust
    wire need_adj = (sum_temp_trunc > 9);

    // BCD correction logic
    assign Sum = need_adj ? (sum_temp_trunc + 4'd6) : sum_temp_trunc;
    assign Cout = need_adj ? carry_temp : 1'b0;

endmodule

module adder_bcd (
    input  [3:0] A,   // First BCD number (0-9)
    input  [3:0] B,   // Second BCD number (0-9)
    input  Cin,       // Input carry
    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry
);
    wire [4:0] temp_sum;
    assign temp_sum = A + B + Cin;

    // Check if adjustment is needed (>=10)
    wire need_adjust = (temp_sum >= 5'd10);

    // BCD adjustment logic
    assign Sum = need_adjust ? (temp_sum[3:0] + 4'd6) : temp_sum[3:0];
    assign Cout  = need_adjust ? 1'b1 : 1'b0;
endmodule

