    input [2:0] B,
    output A_greater,
    output A_equal,
    output A_less
);

wire [2:0] A_greater_than_B;
wire [2:0] A_less_than_B;
wire [2:0] A_equal_bit;

// Generate A_greater_than_B and A_less_than_B with cascable carry-like signals
genvar i;
generate
    for (i=2; i>=0; i=i-1) begin : gt_and_lt
        if (i == 2) begin
            assign A_greater_than_B[i] = (A[i] & ~B[i]);
            assign A_less_than_B[i] = (~A[i] & B[i]);
        end else begin
            assign A_greater_than_B[i] = (A[i] & ~B[i]) | ((A[i] == B[i]) & A_greater_than_B[i+1]);
            assign A_less_than_B[i] = (~A[i] & B[i]) | ((A[i] == B[i]) & A_less_than_B[i+1]);
        end
    end
endgenerate

// Generate A_equal_bit (XNOR for each bit)
generate
    for (i=2; i>=0; i=i-1) begin : xnor
        assign A_equal_bit[i] = (A[i] == B[i]);
    end
endgenerate

// Assign outputs based on generated signals
assign A_greater = A_greater_than_B[2];
assign A_equal  = &A_equal_bit; // AND of all A_equal_bit bits
assign A_less   = A_less_than_B[2];

endmodule

