    input [3:0] B,   // Second 4-bit input operand
    output A_greater, 
    output A_equal,   
    output A_less     
);

    // Sign-extend inputs to 6 bits for accurate comparison
    wire [5:0] A_ext = { {2{A[3]}}, A };
    wire [5:0] B_ext = { {2{B[3]}}, B };

    // Perform comparisons using extended values
    assign A_greater = (A_ext > B_ext);
    assign A_equal   = (A_ext == B_ext);
