module comparator_4bit(
    input [3:0] A,   // First 4-bit input operand
    input [3:0] B,   // Second 4-bit input operand
    output A_greater, 
    output A_equal,   
    output A_less     
);

    // Generate signals for each bit (A > B when A's bit is 1 and B's is 0)
    wire G0, G1, G2, G3;
    assign G0 = A[0] & ~B[0];
    assign G1 = A[1] & ~B[1];
    assign G2 = A[2] & ~B[2];
    assign G3 = A[3] & ~B[3];

    // Compute A_greater as AND of all generate signals
    assign A_greater = G0 & G1 & G2 & G3;

    // Compute difference signals for each bit (A xnor B)
    wire D0, D1, D2, D3;
    assign D0 = A[0] ~^ B[0];
    assign D1 = A[1] ~^ B[1];
    assign D2 = A[2] ~^ B[2];
    assign D3 = A[3] ~^ B[3];

    // Compute A_equal as AND of all difference signals
    assign A_equal = D0 & D1 & D2 & D3;

    // Compute A_less as OR of (difference & higher AND masks)
    wire L0, L1, L2, L3;
    assign L0 = D0; // A[0] < B[0] (no higher bits, so A_less is 0 only if A[0] != B[0])
    assign L1 = D1 & G0; // A[1] < B[1] if A[1] is 1, B[1] is 0, and lower bits are equal
    assign L2 = D2 & G0 & G1; // A[2] < B[2] with previous conditions
    assign L3 = D3 & G0 & G1 & G2; // A[3] < B[3] with previous conditions
    assign A_less = L0 | L1 | L2 | L3;

endmodule

module comparator_4bit(
    input [3:0] A,   // First 4-bit input operand
    input [3:0] B,   // Second 4-bit input operand
    output A_greater, 
    output A_equal,   
    output A_less     
);

    // Precompute XOR bits for each position
    wire [3:0] xor_bits = A ^ B;

    // Calculate sum and carry for each bit (using full adder logic)
    wire [4:1] carry;  // carry[0] is carry-in (0), carry[1] to carry[4] are computed carries

    assign carry[0] = 1'b0;  // Initial carry-in

    // Bit 0: sum[0] and carry[1]
    assign xor_bits[0] ^ carry[0] ^ B[0]; // Sum bit (XOR)
    assign carry[1] = (xor_bits[0] & B[0]) | (carry[0] & xor_bits[0]); // Carry-out (Majority)

    // Bit 1: sum[1] and carry[2]
    assign xor_bits[1] ^ carry[1] ^ B[1];
    assign carry[2] = (xor_bits[1] & B[1]) | (carry[1] & xor_bits[1]);

    // Bit 2: sum[2] and carry[3]
    assign xor_bits[2] ^ carry[2] ^ B[2];
    assign carry[3] = (xor_bits[2] & B[2]) | (carry[2] & xor_bits[2]);

    // Bit 3: sum[3] and carry[4]
    assign xor_bits[3] ^ carry[3] ^ B[3];
    assign carry[4] = (xor_bits[3] & B[3]) | (carry[3] & xor_bits[3]);

    // Determine outputs based on sum and carry
    assign A_equal = (xor_bits == 4'b0) && (carry[4] == 1'b0); // No difference and no borrow
    assign A_less  = carry[4];                                // Borrow flag (MSB carry)
    assign A_greater = ~A_equal;                               // Not equal to A_less (A_equal is 1 only if equal)

endmodule

module counter_12 
