module freq_divbyeven(
    input clk,
    input rst_n,
    output clk_div,
    reg clk_div;
    parameter NUM_DIV = 6;

    reg [4:0] counter;

    // Counter logic with active-low reset
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            counter <= 5'b0;
        end else begin
            if (counter == NUM_DIV - 1) begin
                counter <= 5'b0;
            end else begin
