    // Output toggle logic synchronized to counter
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            clk_div <= 1'b0;
        end else if (counter == (NUM_DIV / 2 - 1)) begin
            clk_div <= ~clk_div;
