module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

reg [3:0] reg_a;
reg [3:0] intermediate_reg;

// Latch data_in into reg_a when data_en is high in clk_a domain
always @(posedge clk_a or negedge arstn) begin
	if (!arstn) begin
		reg_a <= 4'b0;
	end
	else begin
		if (data_en) begin
			reg_a <= data_in;
		end
	end
end

// Two-stage synchronizer for data_en in clk_b domain
always @(posedge clk_b or negedge brstn) begin
	if (!brstn) begin
		intermediate_reg <= 4'b0;
	end
	else begin
		intermediate_reg <= reg_a;
	end
end

// Update dataout with synchronized data_en when it's high in clk_b domain
always @(posedge clk_b or negedge brstn) begin
	if (!brstn) begin
		dataout <= 4'b0;
	end
	else begin
		if (intermediate_reg[3]) begin // MSB indicates data_en
			dataout <= intermediate_reg;
		end
	end
end

endmodule

module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

	// clk_a domain signals
	reg [3:0] data_reg;

	// clk_b domain signals
	reg sync_en_1, sync_en_2;
	reg [3:0] data_sync_1, data_sync_2;

	// Capture data_in when data_en is asserted in clk_a
	always @(posedge clk_a or negedge arstn) begin
		if (!arstn) begin
			data_reg <= 4'b0;
		end else begin
			if (data_en) begin
				data_reg <= data_in;
			end
		end
	end

	// Synchronize data_en and data_reg to clk_b domain
	always @(posedge clk_b or negedge brstn) begin
		if (!brstn) begin
			{sync_en_1, sync_en_2} <= 2'b0;
			{data_sync_1, data_sync_2} <= 8'b0;
			dataout <= 4'b0;
	 end
		end else begin
			// Two-stage sync for enable signal
			sync_en_1 <= data_en;
			sync_en_2 <= sync_en_1;

			// Two-stage sync for data
			data_sync_1 <= data_reg;
			data_sync_2 <= data_sync_1;

			 // Update output with synchronized data when enable is detected
			if (sync_en_2) begin
				dataout <= data_sync_2[3:0];
		 end
		end
	end

endmodule

