always @(*) begin
    case (current_state)
        S_RESET: next_state = IN ? S_B : S_RESET;
        S_B:     next_state = IN ? S_BB : S_RESET;
        S_BB:    next_state = IN ? S_BBC : S_RESET;
        S_BBC:   next_state = IN ? S_BBCB : S_RESET;
        S_BBCB:  next_state = IN ? S_B : S_RESET;
        default: next_state = S_RESET;
    endcase
end

// Output logic for MATCH
always @(posedge CLK or posedge RST) begin
    if (RST) begin
        MATCH <= 1'b0;
    end else begin
        MATCH <= (current_state == S_BBCB);
    end
end

endmodule

