                crc_reg <= {1'b0, crc_reg[3:1]} ^ (d[3] ? 4'b0011 : 4'b0);
            end
            valid_reg <= (cnt == 2'd3);
        end
    end

    assign dout = crc_reg[3];
    assign valid_out = valid_reg;

endmodule

module parallel2serial(
    input clk,
    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);

reg [3:0] shift_reg;
reg [1:0] counter;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        shift_reg <= 4'b0;
        counter <= 2'b0;
    end else begin
        shift_reg <= {shift_reg[2:0], (shift_reg[0] ^ (counter == 2'b11))};
        counter <= (counter == 2'b11) ? 2'b0 : counter + 1;
    end
end

assign valid_out = (counter == 2'b11);
assign dout = shift_reg[3];

endmodule

