module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );

     reg [1:0] zero_count;
     reg [1:0] state;

     parameter IDLE = 2'b00;
     parameter DETECTED = 2'b01;
     parameter READY = 2'b10;

     always @(posedge clk or negedge rst_n) begin
         if (~rst_n) begin
             zero_count <= 2'b00;
             state <= IDLE;
         end else begin
             case (state)
                 IDLE: begin
                     if (data_in == 1'b0) begin
                         zero_count <= zero_count + 1;
                         if (zero_count == 2'b10) begin
                             state <= DETECTED;
                             zero_count <= 2'b00;
                         end
                     end else begin
                         zero_count <= 2'b00;
                     end
                 end
                 DETECTED: begin
                     state <= READY;
                 end
                 READY: begin
                     if (data_in == 1'b1) begin
                         zero_count <= zero_count + 1;
                         if (zero_count == 2'b10) begin
                             state <= IDLE;
                             zero_count <= 2'b00;
                         end
                     end else begin
                         zero_count <= 2'b00;
                     end
                 end
                 default: begin
                     state <= IDLE;
                     zero_count <= 2'b00;
                 end
             endcase
         end
     end

     assign sequence_detected = (state == DETECTED);

endmodule
